<?php
namespace App\Http\Controllers;
use App\Http\Requests\StoreBranchRequest; use App\Modules\Operations\Models\{Assignment,Branch,StaffProfile}; use App\Modules\Tasks\Models\TaskExecution; use Illuminate\Database\Eloquent\Builder; use Illuminate\Http\RedirectResponse; use Illuminate\Http\Request; use Illuminate\View\View;
class BranchController extends Controller { public function index(Request $r): View { $q=Branch::query()->withCount(['assignments','staffProfiles'])->when($r->filled('search'),fn(Builder $q)=>$q->where(fn(Builder $n)=>$n->where('name','like','%'.$r->string('search').'%')->orWhere('code','like','%'.$r->string('search').'%')))->when($r->filled('status'),fn(Builder $q)=>$q->where('status',$r->string('status'))); return view('tenant.operations.branches',['branches'=>$q->orderBy('name')->paginate(10)->withQueryString(),'summary'=>['total'=>Branch::count(),'active'=>Branch::where('status','active')->count(),'inactive'=>Branch::where('status','inactive')->count(),'assigned_staff'=>StaffProfile::whereNotNull('branch_id')->count()]]); } public function create(): View { return view('tenant.operations.branch-form'); } public function store(StoreBranchRequest $r): RedirectResponse { $branch=Branch::create($r->validated()); return redirect()->route('operations.branches.show',$branch)->with('success','Sucursal creada correctamente.'); } public function show(Branch $branch): View { return view('tenant.operations.branch-show',['branch'=>$branch,'inUse'=>$this->inUse($branch)]); } public function edit(Branch $branch): View { return view('tenant.operations.branch-form',compact('branch')); } public function update(StoreBranchRequest $r,Branch $branch): RedirectResponse { $branch->update($r->validated()); return redirect()->route('operations.branches.show',$branch)->with('success','Sucursal actualizada correctamente.'); } public function toggle(Branch $branch): RedirectResponse { $branch->update(['status'=>$branch->status==='active'?'inactive':'active']); return back()->with('success','Estado de sucursal actualizado.'); } public function destroy(Branch $branch): RedirectResponse { if($this->inUse($branch)) return back()->withErrors(['branch'=>'Esta sucursal tiene colaboradores, asignaciones o historial. Solo puede desactivarse.']); $branch->delete(); return redirect()->route('operations.branches')->with('success','Sucursal eliminada.'); } private function inUse(Branch $branch): bool { return $branch->staffProfiles()->exists() || $branch->assignments()->exists() || TaskExecution::query()->where('branch_id',$branch->id)->exists(); } }
